// Cloudflare Worker entry: the Next.js app built by OpenNext, plus the cron
// trigger every 10 minutes. Gmail is read on every run (small steps: the free
// plan allows 50 requests a run); once an hour the purge of old catalog chats and
// the status mail of
// the customer panel and the due reminders of board cards. Each job is its own invocation, so each has its own limit.
// @ts-ignore: generated by `opennextjs-cloudflare build` (missing before the first build)
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

const run = (path: string, env: Env, ctx: Ctx) =>
  ctx.waitUntil(
    handler.fetch(new Request(`https://cron.internal/api/cron/${path}`, { headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } }), env, ctx)
      .then(async (res: Response) => console.log(`[nutrikal] ${path} cron: ${res.status} ${await res.text()}`)),
  );

export default {
  fetch: handler.fetch,

  async scheduled(controller: { cron: string; scheduledTime: number }, env: Env, ctx: Ctx) {
    if (controller.cron === "0 * * * *") {
      run("catalog-purge", env, ctx);
      run("portal-mail", env, ctx);
      run("board-due", env, ctx);
      run("trash-purge", env, ctx);
      return;
    }
    // Every minute: notifications to phones and computers (Web Push)
    if (controller.cron === "* * * * *") {
      run("push", env, ctx);
      return;
    }
    run("gmail-sync", env, ctx);
  },
};
